<script setup lang="ts">
const props=defineProps<{rows:Record<string,any>[];statuses:Record<string,any>[];search:string}>()
const emit=defineEmits<{updateSearch:[value:string];edit:[row:Record<string,any>]}>()
const active=ref(''), sort=ref('record_date'), direction=ref<'asc'|'desc'>('desc')
const visible=computed(()=>[...props.rows].filter(row=>!active.value||row.status_name===active.value).sort((a,b)=>{const x=String(a[sort.value]??''),y=String(b[sort.value]??'');return direction.value*(x.localeCompare(y,undefined,{numeric:true}))}))
const toggle=(key:string)=>{direction.value=sort.value===key?(direction.value==='asc'?'desc':'asc'):'asc';sort.value=key}
const money=(n:number)=>new Intl.NumberFormat('en-TZ',{maximumFractionDigits:0}).format(Number(n)||0)+' TZS'
const date=(v?:string)=>v?new Intl.DateTimeFormat('en-TZ',{day:'numeric',month:'short',year:'numeric'}).format(new Date(`${v}T00:00:00`)):'—'
</script>
<template><div class="toolbar"><input :value="search" placeholder="Search client, order or invoice" @input="emit('updateSearch',($event.target as HTMLInputElement).value)"><span>{{visible.length}} orders</span></div><div class="chips"><button :class="{active:!active}" @click="active=''">All</button><button v-for="s in statuses" :key="s.id" :class="{active:active===s.name}" @click="active=s.name">{{s.name}}</button></div><article class="table-card"><table><thead><tr><th @click="toggle('record_number')">ORDER</th><th @click="toggle('client_name')">CLIENT</th><th @click="toggle('record_date')">DATE</th><th @click="toggle('status_name')">STATUS</th><th @click="toggle('grand_total_minor')">TOTAL</th><th>BILLING STATUS</th><th></th></tr></thead><tbody><tr v-for="r in visible" :key="r.id"><td>{{r.record_number||'—'}}</td><td><strong>{{r.client_name}}</strong><small>{{r.contacts||'No contact details'}}</small></td><td>{{date(r.record_date)}}</td><td><em :style="{'--c':r.status_color}">{{r.status_name}}</em></td><td><strong>{{money(r.grand_total_minor)}}</strong></td><td><em class="billing" :class="String(r.payment_status).toLowerCase().replaceAll(' ','-')">{{r.payment_status||'Pending'}}</em></td><td><button @click="emit('edit',r)">Edit</button></td></tr></tbody></table><p v-if="!visible.length">No matching orders.</p></article></template>
<style scoped>.toolbar{display:flex;justify-content:space-between;margin-bottom:12px}.toolbar input{width:400px;max-width:70vw;border:1px solid var(--border);border-radius:8px;padding:11px}.chips{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:15px}.chips button{border:1px solid var(--border);background:#fff;border-radius:99px;padding:6px 10px;color:var(--muted);cursor:pointer}.chips button.active{background:var(--brand);color:#fff;border-color:var(--brand)}.table-card{background:#fff;border:1px solid var(--border);border-radius:12px;overflow:auto}table{width:100%;border-collapse:collapse}th{text-align:left;padding:15px 20px;background:#faf8f2;font-size:10px;color:var(--muted);cursor:pointer}td{padding:15px 20px;border-top:1px solid #eee8dd}small{display:block;color:var(--muted)}em{--c:#64748b;font-style:normal;background:color-mix(in srgb,var(--c) 13%,white);color:var(--c);padding:5px 8px;border-radius:99px;font-size:11px;font-weight:800}td button{border:0;background:none;color:var(--brand);font-weight:800;cursor:pointer}</style>
